ruleContent.content:
@js:
var d = JSON.parse(result);
var v = String(this.source.getVariable()).split(',');
var mode = parseInt(v[0]) || 0;

var content = '';

if (mode == 0) {
  content = d.data.content || '';
  // 首段补全角空格缩进（API 首段无缩进）
  if (content) {
    var ci = 0;
    while (ci < content.length && (content.charAt(ci) === '\n' || content.charAt(ci) === ' ')) ci++;
    if (ci < content.length && content.charAt(ci) !== '\u3000') {
      content = content.substring(0, ci) + '\u3000\u3000' + content.substring(ci);
    }
  }
} else if (mode == 1) {
  content = d.data.audio_url || d.data.content || '';
} else if (mode == 2) {
  content = d.data.images || '';
} else if (mode == 3) {
  content = d.data.video_url || '';
}

if (mode == 0 && typeof CMTOFF !== 'undefined' && !CMTOFF()) {
  var bid = '';
  var m = baseUrl.match(/bid=(\d+)/);
  if (m) bid = m[1];
  try {
    var all = [];
    var offset = 0;
    var LIMIT = 100;
    while (all.length < LIMIT) {
      var cr = JSON.parse(java.ajax('https://fq.taijiwang.top/api/comment?book_id=' + bid + '&count=50&offset=' + offset));
      var cmts = cr.data.data.comment;
      if (!cmts || cmts.length === 0) break;
      all = all.concat(cmts);
      if (!cr.data.data.has_more) break;
      offset += 50;
    }
    if (all.length > 0) {
      content += '\n\n━━━━━━━━━━━━━━━━━━\n💬 本书书评（共' + all.length + '条）\n━━━━━━━━━━━━━━━━━━\n';
      for (var i = 0; i < all.length; i++) {
        var c = all[i];
        var nick = (c.user_info && c.user_info.user_name) ? c.user_info.user_name : '匿名';
        var digg = c.digg_count || 0;
        var rep = c.reply_count || 0;
        var sc = c.score || '';
        var txt = String(c.text).split('\n').join(' ');
        var line = '👤 ' + nick;
        if (sc) line += ' ⭐' + sc;
        line += ' 👍' + digg + ' 💬' + rep;
        content += line + '\n📝 ' + txt + '\n';
      }
    }
  } catch (e) {}
}
result = content;

ruleSearch.bookList:
@js:
var d = JSON.parse(result);
var tabs = d.data.search_tabs;
var v = String(this.source.getVariable()).split(",");
var idx = parseInt(v[0]) || 0;
var typeValues = [3, 2, 8, 11];
var currentType = typeValues[idx] !== undefined ? typeValues[idx] : 3;
var books = [];
for (var i = 0; i < tabs.length; i++) {
    if (tabs[i].tab_type == currentType && tabs[i].data) {
        for (var j = 0; j < tabs[i].data.length; j++) {
            var g = tabs[i].data[j];
            if (currentType == 11) {
                // === 短剧: 从 video_data 取, 统一成书结构 ===
                var vd = g.video_data;
                if (vd) {
                    for (var k = 0; k < vd.length; k++) {
                        var it = vd[k];
                        var cat = '';
                        try {
                            var cs = JSON.parse(it.category_schema || '[]');
                            if (cs[0]) cat = cs[0].name;
                        } catch (e) {}
                        books.push(JSON.stringify({
                            book_name: it.title || it.raw_book_name || '',
                            author: it.author || '',
                            category: cat,
                            abstract: it.rec_text || it.sub_title || '',
                            thumb_url: it.cover || it.horiz_cover || '',
                            book_id: it.series_id || it.vid || ''
                        }));
                    }
                }
            } else {
                // === 小说/听书/漫画: 原有逻辑 ===
                var bd = g.book_data;
                if (bd) {
                    for (var k = 0; k < bd.length; k++) {
                        books.push(JSON.stringify(bd[k]));
                    }
                }
            }
        }
    }
}
result = books;

ruleToc.chapterList:
@js:
var d = (typeof result === 'string') ? JSON.parse(result) : result;
var obj = d.data.data;
var clwv = obj.chapterListWithVolume || [];
var vnl = obj.volumeNameList || [];
var arr = [];
for (var i = 0; i < clwv.length; i++) {
  var vol = clwv[i];
  if (vol.length > 0) {
    var vn = vnl[i] || ('第' + (i + 1) + '卷');
    arr.push(JSON.stringify({title: vn, isVolume: true, itemId: vol[0].itemId}));
  }
  for (var j = 0; j < vol.length; j++) {
    var ch = vol[j];
    ch.isVolume = false;
    arr.push(JSON.stringify(ch));
  }
}
arr;

